#!/bin/bash
# Laudate â€“ inÅ¡talÃ¡tor pre Orange Pi PC a Raspberry Pi 5 / 4 (Armbian, Raspberry Pi OS, Debian, Ubuntu).
# SÃºbor obsahuje hotovÃº aplikÃ¡ciu, na zariadenÃ­ sa niÄ nekompiluje.
#
# Spustenie:   sudo bash tvdisplay-orangepi-install.sh
# VoÄ¾by:       --yes            bez otÃ¡zok (TV Ã¡no, PowerPoint Ã¡no, bez PIN a tokenu)
#              --no-kiosk       nezobrazovaÅ¥ aplikÃ¡ciu na TV pripojenej k tomuto zariadeniu
#              --no-powerpoint  neinÅ¡talovaÅ¥ LibreOffice
#              --nas-url=URL    piesne, fotky a prezentÃ¡cie v prieÄinku na NAS (Synology WebDAV),
#                               napr. https://mojnas.synology.me:5006/tvdisplay/kostol-sv-martina
#              --nas-user=MENO, --nas-password=HESLO   prihlÃ¡senie do NAS
#              --nas-ignore-cert  prijaÅ¥ certifikÃ¡t vystavenÃ½ samotnÃ½m NAS (https v miestnej sieti)
#                               pri aktualizÃ¡cii tieto voÄ¾by zmenia nastavenia, --nas-url= napojenie zruÅ¡Ã­
#              --tailscale      spojenie s NAS v inej sieti cez Tailscale (bez nastavovania routera);
#                               bez kÄ¾ÃºÄa sa zobrazÃ­ odkaz na prihlÃ¡senie do Tailscale ÃºÄtu
#              --tailscale-authkey=KÄ½ÃšÄŒ   prihlÃ¡senie do Tailscale kÄ¾ÃºÄom (admin konzola Tailscale -> Settings -> Keys)
#              --no-tailscale   nepÃ½taÅ¥ sa na Tailscale
#              --church-url=URL piesne kostola z administrÃ¡cie (Docker na NAS, adresa zo zÃ¡loÅ¾ky Kostoly)
#              --no-buttons     neobsluhovaÅ¥ fyzickÃ© tlaÄidlÃ¡ na pinoch GPIO (reÅ¡tart aplikÃ¡cie / zariadenia)
#              --wifi-ssid=NÃZOV --wifi-password=HESLO   pripojenie na Wi-Fi v kostole (Raspberry Pi mÃ¡ Wi-Fi
#                               v sebe, Orange Pi PC potrebuje USB Wi-Fi adaptÃ©r); sieÅ¥ nemusÃ­ byÅ¥ teraz v dosahu
#
# OpÃ¤tovnÃ© spustenie aplikÃ¡ciu aktualizuje. Nastavenia, piesne ani prezentÃ¡cie nezmenÃ­.
set -euo pipefail

APP_DIR=/opt/tvdisplay
NODE_DIR=/opt/tvdisplay-node
HOME_DIR=/var/lib/tvdisplay
APP_USER=tvdisplay
NODE_MAJOR=22
APP_PORT=5173
STATE_PORT=3002

ASSUME_YES=0
WANT_KIOSK=ask
WANT_POWERPOINT=ask
CHURCH_URL_SET=0
CHURCH_DATA_URL=""
NAS_SET=0
NAS_URL=""
NAS_USER=""
NAS_PASSWORD=""
NAS_IGNORE_CERT=0
WANT_TAILSCALE=ask
TAILSCALE_AUTHKEY=""
WANT_BUTTONS=yes
WIFI_SSID=""
WIFI_PASSWORD=""
for arg in "$@"; do
  case "$arg" in
    --yes) ASSUME_YES=1 ;;
    --no-kiosk) WANT_KIOSK=no ;;
    --no-powerpoint) WANT_POWERPOINT=no ;;
    --church-url=*) CHURCH_URL_SET=1; CHURCH_DATA_URL="${arg#--church-url=}" ;;
    --nas-url=*) NAS_SET=1; NAS_URL="${arg#--nas-url=}" ;;
    --nas-user=*) NAS_SET=1; NAS_USER="${arg#--nas-user=}" ;;
    --nas-password=*) NAS_SET=1; NAS_PASSWORD="${arg#--nas-password=}" ;;
    --nas-ignore-cert) NAS_SET=1; NAS_IGNORE_CERT=1 ;;
    --tailscale) WANT_TAILSCALE=yes ;;
    --tailscale-authkey=*) WANT_TAILSCALE=yes; TAILSCALE_AUTHKEY="${arg#--tailscale-authkey=}" ;;
    --no-tailscale) WANT_TAILSCALE=no ;;
    --no-buttons) WANT_BUTTONS=no ;;
    --wifi-ssid=*) WIFI_SSID="${arg#--wifi-ssid=}" ;;
    --wifi-password=*) WIFI_PASSWORD="${arg#--wifi-password=}" ;;
    *) echo "NeznÃ¡ma voÄ¾ba: $arg"; exit 2 ;;
  esac
done

SELF=$(readlink -f "$0")
if [ "$(id -u)" -ne 0 ]; then
  exec sudo bash "$SELF" "$@"
fi

step() { echo; echo "==> $*"; }
warn() { echo "POZOR: $*" >&2; }
die() { echo "CHYBA: $*" >&2; exit 1; }

ask_yes() { # otÃ¡zka, predvolene Ã¡no
  [ "$ASSUME_YES" -eq 1 ] && return 0
  local answer
  read -r -p "$1 [A/n]: " answer </dev/tty || return 0
  case "$answer" in [nN]*) return 1 ;; *) return 0 ;; esac
}

ask_value() { # otÃ¡zka, skrytÃ½ vstup: 1 = Ã¡no
  [ "$ASSUME_YES" -eq 1 ] && return 0
  local answer=""
  if [ "${2:-0}" -eq 1 ]; then
    read -r -s -p "$1: " answer </dev/tty || true
    echo >&2
  else
    read -r -p "$1: " answer </dev/tty || true
  fi
  printf '%s' "$answer"
}

apt_candidate() { # existuje balÃ­k v repozitÃ¡ri?
  local candidate
  candidate=$(apt-cache policy "$1" 2>/dev/null | awk '/Candidate:/ {print $2; exit}')
  [ -n "$candidate" ] && [ "$candidate" != "(none)" ]
}

apt_install() {
  DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends "$@"
}

tailscale_connected() { # je zariadenie prihlÃ¡senÃ© do Tailscale?
  command -v tailscale >/dev/null && tailscale status >/dev/null 2>&1
}

# OverÃ­, Äi sÃº piesne dostupnÃ© (po pripojenÃ­ Tailscale, keÄ uÅ¾ je nainÅ¡talovanÃ½ curl)
check_sources() {
  if [ -n "$NAS_URL" ]; then
    local cert=()
    [ "$NAS_IGNORE_CERT" -eq 1 ] && cert=(-k)
    local status
    status=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 15 "${cert[@]}" -u "$NAS_USER:$NAS_PASSWORD" "$NAS_URL/songs.json" 2>/dev/null || true)
    case "$status" in
      200) echo "PrieÄinok na NAS je dostupnÃ½." ;;
      404) echo "PrieÄinok na NAS je prÃ¡zdny â€“ piesne, fotky a prezentÃ¡cie tohto zariadenia sa naÅˆ nahrajÃº pri prvom spustenÃ­." ;;
      401|403) warn "NAS odmietol prihlÃ¡senie â€“ skontroluj meno, heslo a prÃ¡vo pouÅ¾Ã­vateÄ¾a na WebDAV." ;;
      000) warn "NAS sa nepodarilo dosiahnuÅ¥ ($NAS_URL). Skontroluj adresu a spojenie (Tailscale: sudo tailscale status). Pri https s vlastnÃ½m certifikÃ¡tom NAS pridaj --nas-ignore-cert." ;;
      *) warn "NAS vrÃ¡til chybu $status pre $NAS_URL." ;;
    esac
  fi
  if [ -n "$CHURCH_DATA_URL" ]; then
    if curl -fsS -o /dev/null --max-time 10 "$CHURCH_DATA_URL/songs.json"; then
      echo "AdministrÃ¡cia kostola je dostupnÃ¡."
    else
      warn "Adresu $CHURCH_DATA_URL sa teraz nepodarilo naÄÃ­taÅ¥. Skontroluj ju; Orange Pi to bude skÃºÅ¡aÅ¥ kaÅ¾dÃº minÃºtu."
    fi
  fi
}

# --- Kontroly ------------------------------------------------------------

case "$(uname -m)" in
  armv7l) NODE_ARCH=armv7l ;;
  aarch64) NODE_ARCH=arm64 ;;
  x86_64) NODE_ARCH=x64 ;;
  *) die "NepodporovanÃ½ procesor: $(uname -m)" ;;
esac
command -v apt-get >/dev/null || die "InÅ¡talÃ¡tor potrebuje systÃ©m s apt (Armbian, Debian, Ubuntu)."

PAYLOAD_LINE=$(grep -anm1 '^__PAYLOAD_BELOW__$' "$SELF" | cut -d: -f1)
[ -n "$PAYLOAD_LINE" ] || die "SÃºbor je poÅ¡kodenÃ½, chÃ½ba v Åˆom aplikÃ¡cia."

FREE_MB=$(df -Pm / | awk 'NR==2 {print $4}')
[ "$FREE_MB" -ge 1000 ] || die "Na karte je voÄ¾nÃ½ch iba $FREE_MB MB, treba aspoÅˆ 1 GB."

# Doska: Raspberry Pi mÃ¡ inÃ© ÄÃ­sla pinov GPIO ako Orange Pi (fyzickÃ© piny na konektore sÃº tie istÃ©)
BOARD_MODEL=$(tr -d '\0' 2>/dev/null </proc/device-tree/model || true)
case "$BOARD_MODEL" in
  *"Raspberry Pi"*) BOARD=rpi; BOARD_NAME="Raspberry Pi" ;;
  *"Orange Pi"*) BOARD=orangepi; BOARD_NAME="Orange Pi" ;;
  *) BOARD=other; BOARD_NAME="zariadenie" ;;
esac

# Orange Pi PC nemÃ¡ hodiny s batÃ©riou: bez sprÃ¡vneho Äasu zlyhÃ¡ HTTPS aj liturgickÃ¡ tÃ©ma
timedatectl set-ntp true 2>/dev/null || true

# --- OtÃ¡zky (vÅ¡etky naraz, potom uÅ¾ inÅ¡talÃ¡cia beÅ¾Ã­ sama) ----------------

echo "Laudate â€“ inÅ¡talÃ¡cia na ${BOARD_MODEL:-$(uname -m)}"

ENV_EXISTS=0
[ -f "$APP_DIR/.env" ] && ENV_EXISTS=1
CONTROL_PIN=""
GITHUB_TOKEN=""
if [ "$ENV_EXISTS" -eq 0 ]; then
  CONTROL_PIN=$(ask_value "PIN na ovlÃ¡danie (prÃ¡zdne = bez PIN)")
  if [ "$NAS_SET" -eq 0 ] && [ "$CHURCH_URL_SET" -eq 0 ]; then
    echo "Piesne, fotky a prezentÃ¡cie mÃ´Å¾u byÅ¥ v prieÄinku na NAS (Synology, balÃ­k WebDAV Server),"
    echo "napr. https://mojnas.synology.me:5006/tvdisplay/kostol-sv-martina alebo http://192.168.1.10:5005/tvdisplay/kostol-sv-martina"
    NAS_URL=$(ask_value "Adresa prieÄinka na NAS (prÃ¡zdne = piesne z GitHubu)")
    if [ -n "$NAS_URL" ]; then
      NAS_USER=$(ask_value "Meno pouÅ¾Ã­vateÄ¾a na NAS")
      NAS_PASSWORD=$(ask_value "Heslo pouÅ¾Ã­vateÄ¾a na NAS (nezobrazuje sa)" 1)
    fi
  fi
  if [ -z "$CHURCH_DATA_URL" ] && [ -z "$NAS_URL" ]; then
    echo "GitHub token je potrebnÃ½ na trvalÃ© ukladanie Ãºprav piesnÃ­. MoÅ¾no ho doplniÅ¥ aj neskÃ´r v $APP_DIR/.env"
    GITHUB_TOKEN=$(ask_value "GitHub token (prÃ¡zdne = preskoÄiÅ¥, nezobrazuje sa)" 1)
  fi
fi
CHURCH_DATA_URL="${CHURCH_DATA_URL%/}"
NAS_URL="${NAS_URL%/}"
# Pri aktualizÃ¡cii platia nastavenia NAS z .env, pokiaÄ¾ ich voÄ¾by nemenia
env_value() { sed -n "s/^$1=//p" "$APP_DIR/.env" | tail -n1; }
if [ "$ENV_EXISTS" -eq 1 ]; then
  if [ "$NAS_SET" -eq 0 ]; then
    NAS_URL=$(env_value NAS_URL)
    [ "$(env_value NAS_IGNORE_CERT)" = 1 ] && NAS_IGNORE_CERT=1
  fi
  [ -z "$NAS_USER" ] && NAS_USER=$(env_value NAS_USER)
  [ -z "$NAS_PASSWORD" ] && NAS_PASSWORD=$(env_value NAS_PASSWORD)
fi

# NAS v inej sieti: Tailscale vytvorÃ­ Å¡ifrovanÃ© spojenie bez presmerovania portov na routeri
if [ "$WANT_TAILSCALE" = ask ]; then
  WANT_TAILSCALE=no
  if [ -n "$NAS_URL" ] && [ "$ASSUME_YES" -eq 0 ] && ! tailscale_connected; then
    if ask_yes "Je NAS v inej sieti ako toto zariadenie? PripojiÅ¥ sa k nemu cez Tailscale?"; then WANT_TAILSCALE=yes; fi
  fi
fi
if [ "$WANT_TAILSCALE" = yes ] && [ -z "$TAILSCALE_AUTHKEY" ] && ! tailscale_connected; then
  echo "KÄ¾ÃºÄ vytvorÃ­Å¡ v admin konzole Tailscale (Settings -> Keys -> Generate auth key). Bez kÄ¾ÃºÄa sa zobrazÃ­ odkaz na prihlÃ¡senie."
  TAILSCALE_AUTHKEY=$(ask_value "Tailscale kÄ¾ÃºÄ (prÃ¡zdne = prihlÃ¡siÅ¥ sa odkazom, nezobrazuje sa)" 1)
fi

if [ "$WANT_KIOSK" = ask ]; then
  if ask_yes "ZobrazovaÅ¥ aplikÃ¡ciu na TV pripojenej cez HDMI k tomuto zariadeniu?"; then WANT_KIOSK=yes; else WANT_KIOSK=no; fi
fi
if [ "$WANT_POWERPOINT" = ask ]; then
  if ask_yes "NainÅ¡talovaÅ¥ podporu PowerPointu (LibreOffice, pribliÅ¾ne 500 MB)?"; then WANT_POWERPOINT=yes; else WANT_POWERPOINT=no; fi
fi

DISPLAY_MANAGER_ACTIVE=0
if [ "$WANT_KIOSK" = yes ] && systemctl is-active --quiet display-manager 2>/dev/null; then
  DISPLAY_MANAGER_ACTIVE=1
  if ! ask_yes "BeÅ¾Ã­ tu pracovnÃ© prostredie. MÃ¡ ho po reÅ¡tarte nahradiÅ¥ obrazovka Laudate?"; then
    WANT_KIOSK=no
    DISPLAY_MANAGER_ACTIVE=0
    warn "Obrazovka sa nenastavÃ­. Otvor http://localhost:$APP_PORT/#display v prehliadaÄi ruÄne."
  fi
fi

# --- SystÃ©movÃ© balÃ­ky ----------------------------------------------------

step "Aktualizujem zoznam balÃ­kov"
apt-get update || warn "Zoznam balÃ­kov sa nepodarilo celÃ½ obnoviÅ¥, pokraÄujem."
apt_install ca-certificates curl tar xz-utils sudo

# --- Wi-Fi ---------------------------------------------------------------

if [ -n "$WIFI_SSID" ]; then
  step "Nastavujem Wi-Fi \"$WIFI_SSID\""
  if command -v nmcli >/dev/null && systemctl is-active --quiet NetworkManager; then
    WIFI_IF=$(nmcli -t -f DEVICE,TYPE device 2>/dev/null | awk -F: '$2 == "wifi" {print $1; exit}')
    if [ -z "$WIFI_IF" ]; then
      warn "Zariadenie nemÃ¡ Wi-Fi (Orange Pi PC potrebuje USB Wi-Fi adaptÃ©r)."
    else
      nmcli connection delete laudate-wifi >/dev/null 2>&1 || true
      if [ -n "$WIFI_PASSWORD" ]; then
        nmcli connection add type wifi con-name laudate-wifi ifname "$WIFI_IF" ssid "$WIFI_SSID" \
          wifi-sec.key-mgmt wpa-psk wifi-sec.psk "$WIFI_PASSWORD" connection.autoconnect yes >/dev/null
      else
        nmcli connection add type wifi con-name laudate-wifi ifname "$WIFI_IF" ssid "$WIFI_SSID" connection.autoconnect yes >/dev/null
      fi && echo "Wi-Fi je uloÅ¾enÃ¡, zariadenie sa na Åˆu pripojÃ­ samo, keÄ bude v dosahu." \
        || warn "Wi-Fi sa nepodarilo uloÅ¾iÅ¥."
      nmcli connection up laudate-wifi >/dev/null 2>&1 || true
    fi
  else
    warn "Wi-Fi sa dÃ¡ nastaviÅ¥ len so systÃ©mom s NetworkManager (Raspberry Pi OS Bookworm, Armbian). Inak ju nastav cez Raspberry Pi Imager."
  fi
fi

# --- Tailscale (spojenie s NAS v inej sieti) -----------------------------

if [ "$WANT_TAILSCALE" = yes ]; then
  step "PripÃ¡jam Tailscale"
  if ! command -v tailscale >/dev/null; then
    # OficiÃ¡lny inÅ¡talaÄnÃ½ skript Tailscale (pridÃ¡ ich repozitÃ¡r a nainÅ¡taluje balÃ­k)
    curl -fsSL https://tailscale.com/install.sh | sh || warn "Tailscale sa nepodarilo nainÅ¡talovaÅ¥."
  fi
  if command -v tailscale >/dev/null; then
    systemctl enable --now tailscaled >/dev/null 2>&1 || true
    TS_NAME="tvdisplay-$(hostname | tr -cd 'a-zA-Z0-9-')"
    if tailscale_connected; then
      echo "Tailscale je uÅ¾ pripojenÃ½."
    elif [ -n "$TAILSCALE_AUTHKEY" ]; then
      tailscale up --authkey="$TAILSCALE_AUTHKEY" --hostname="$TS_NAME" || warn "PrihlÃ¡senie do Tailscale kÄ¾ÃºÄom zlyhalo. SkÃºs: sudo tailscale up"
    elif [ "$ASSUME_YES" -eq 0 ]; then
      echo "Otvor odkaz, ktorÃ½ sa zobrazÃ­ (napr. v mobile), a prihlÃ¡s sa do Tailscale ÃºÄtu, v ktorom je NAS."
      tailscale up --hostname="$TS_NAME" || warn "Tailscale sa nepripojil. SkÃºs neskÃ´r: sudo tailscale up"
    else
      warn "Tailscale je nainÅ¡talovanÃ½, ale neprihlÃ¡senÃ½. Spusti: sudo tailscale up"
    fi
  fi
fi

command -v curl >/dev/null && check_sources

# --- Node.js -------------------------------------------------------------

if [ -x "$NODE_DIR/bin/node" ] && "$NODE_DIR/bin/node" -v 2>/dev/null | grep -q "^v$NODE_MAJOR\."; then
  step "Node.js $("$NODE_DIR/bin/node" -v) je uÅ¾ nainÅ¡talovanÃ½"
else
  step "InÅ¡talujem Node.js $NODE_MAJOR pre $NODE_ARCH"
  BASE="https://nodejs.org/dist/latest-v$NODE_MAJOR.x"
  SUMS=$(curl -fsSL "$BASE/SHASUMS256.txt") || die "Nepodarilo sa spojiÅ¥ s nodejs.org. Skontroluj internet a dÃ¡tum: $(date)"
  LINE=$(printf '%s\n' "$SUMS" | grep "linux-$NODE_ARCH\.tar\.xz$") || die "Pre $NODE_ARCH nie je Node.js $NODE_MAJOR k dispozÃ­cii."
  NODE_SHA=$(printf '%s' "$LINE" | awk '{print $1}')
  NODE_FILE=$(printf '%s' "$LINE" | awk '{print $2}')
  NODE_TMP=$(mktemp -d)
  curl -fL --progress-bar -o "$NODE_TMP/$NODE_FILE" "$BASE/$NODE_FILE"
  echo "$NODE_SHA  $NODE_TMP/$NODE_FILE" | sha256sum -c --quiet - || die "StiahnutÃ½ Node.js je poÅ¡kodenÃ½."
  rm -rf "$NODE_DIR"
  mkdir -p "$NODE_DIR"
  tar xJf "$NODE_TMP/$NODE_FILE" -C "$NODE_DIR" --strip-components=1 --no-same-owner
  rm -rf "$NODE_TMP"
  "$NODE_DIR/bin/node" -v >/dev/null || die "Node.js sa na tomto systÃ©me nespustÃ­ (potrebuje glibc 2.28, teda Debian 10 alebo novÅ¡Ã­)."
fi

# --- OdkladacÃ­ priestor --------------------------------------------------

# 1 GB RAM nestaÄÃ­ na prehliadaÄ a prevod PowerPointu naraz
SWAP_MB=$(free -m | awk '/^Swap:/ {print $2}')
if [ "${SWAP_MB:-0}" -lt 512 ] && [ ! -f /var/swap.tvdisplay ] && [ "$FREE_MB" -ge 4000 ]; then
  step "VytvÃ¡ram odkladacÃ­ sÃºbor 1 GB"
  if dd if=/dev/zero of=/var/swap.tvdisplay bs=1M count=1024 status=none \
    && chmod 600 /var/swap.tvdisplay && mkswap /var/swap.tvdisplay >/dev/null && swapon /var/swap.tvdisplay; then
    grep -q '/var/swap.tvdisplay' /etc/fstab || echo '/var/swap.tvdisplay none swap sw 0 0' >>/etc/fstab
  else
    rm -f /var/swap.tvdisplay
    warn "OdkladacÃ­ sÃºbor sa nepodarilo vytvoriÅ¥."
  fi
fi

# --- AplikÃ¡cia -----------------------------------------------------------

step "InÅ¡talujem aplikÃ¡ciu do $APP_DIR"
id "$APP_USER" >/dev/null 2>&1 || useradd --system --create-home --home-dir "$HOME_DIR" --shell /bin/bash "$APP_USER"
mkdir -p "$HOME_DIR"
chown "$APP_USER:$APP_USER" "$HOME_DIR"

systemctl stop tvdisplay-kiosk.service 2>/dev/null || true
systemctl stop tvdisplay.service 2>/dev/null || true

PAYLOAD_TMP=$(mktemp -d)
trap 'rm -rf "$PAYLOAD_TMP"' EXIT
tail -n +"$((PAYLOAD_LINE + 1))" "$SELF" | tar xzf - -C "$PAYLOAD_TMP" --no-same-owner

mkdir -p "$APP_DIR/uploads"
rm -rf "$APP_DIR/dist" "$APP_DIR/server" "$APP_DIR/node_modules" "$APP_DIR/Texty"
cp -R "$PAYLOAD_TMP/dist" "$PAYLOAD_TMP/server" "$PAYLOAD_TMP/node_modules" "$PAYLOAD_TMP/Texty" "$PAYLOAD_TMP/package.json" "$APP_DIR/"
# Piesne a obrÃ¡zky iba pri prvej inÅ¡talÃ¡cii, neskÃ´r by prepÃ­sali Ãºpravy
for file in songs.json images.json; do
  [ -f "$APP_DIR/$file" ] || cp "$PAYLOAD_TMP/$file" "$APP_DIR/$file"
done

if [ "$ENV_EXISTS" -eq 0 ]; then
  (
    umask 077
    {
      echo "GITHUB_TOKEN=$GITHUB_TOKEN"
      echo "GITHUB_OWNER=JanKarajos"
      echo "GITHUB_REPO=tvdisplay"
      echo "GITHUB_BRANCH=main"
      echo "CONTROL_PIN=$CONTROL_PIN"
      echo "STATE_PORT=$STATE_PORT"
      echo "APP_PORT=$APP_PORT"
      echo "CHURCH_DATA_URL=$CHURCH_DATA_URL"
      echo "NAS_URL=$NAS_URL"
      echo "NAS_USER=$NAS_USER"
      echo "NAS_PASSWORD=$NAS_PASSWORD"
      echo "NAS_IGNORE_CERT=$NAS_IGNORE_CERT"
    } >"$APP_DIR/.env"
  )
else
  # AktualizÃ¡cia s voÄ¾bami: zmeÅˆ iba zadanÃ© nastavenia, ostatnÃ© ostanÃº
  set_env() {
    sed -i "/^$1=/d" "$APP_DIR/.env"
    printf '%s=%s\n' "$1" "$2" >>"$APP_DIR/.env"
  }
  [ "$CHURCH_URL_SET" -eq 1 ] && set_env CHURCH_DATA_URL "$CHURCH_DATA_URL"
  if [ "$NAS_SET" -eq 1 ]; then
    set_env NAS_URL "$NAS_URL"
    [ -n "$NAS_USER" ] && set_env NAS_USER "$NAS_USER"
    [ -n "$NAS_PASSWORD" ] && set_env NAS_PASSWORD "$NAS_PASSWORD"
    set_env NAS_IGNORE_CERT "$NAS_IGNORE_CERT"
  fi
fi
chown -R "$APP_USER:$APP_USER" "$APP_DIR"
chmod 600 "$APP_DIR/.env"

cat >/etc/systemd/system/tvdisplay.service <<EOF
[Unit]
Description=Laudate server
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=$APP_USER
WorkingDirectory=$APP_DIR
Environment=NODE_ENV=production
Environment=HOME=$HOME_DIR
ExecStart=$NODE_DIR/bin/node server/index.js --serve
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

# --- PowerPoint ----------------------------------------------------------

if [ "$WANT_POWERPOINT" = yes ]; then
  step "InÅ¡talujem LibreOffice (mÃ´Å¾e to trvaÅ¥ aj 15 minÃºt)"
  apt_install libreoffice-impress fonts-dejavu fonts-liberation \
    || warn "LibreOffice sa nepodarilo nainÅ¡talovaÅ¥. PDF budÃº fungovaÅ¥, PowerPoint nie."
fi

# --- Obrazovka na TV -----------------------------------------------------

BROWSER=""
if [ "$WANT_KIOSK" = yes ]; then
  step "Nastavujem obrazovku na TV (mÃ´Å¾e to trvaÅ¥ aj 15 minÃºt)"
  . /etc/os-release 2>/dev/null || true
  if apt_candidate chromium; then
    BROWSER=chromium
  elif [ "${ID:-}" != ubuntu ] && apt_candidate chromium-browser; then
    BROWSER=chromium-browser
  elif apt_candidate firefox-esr; then
    BROWSER=firefox-esr
  fi

  if [ -z "$BROWSER" ]; then
    warn "V repozitÃ¡ri systÃ©mu nie je pouÅ¾iteÄ¾nÃ½ prehliadaÄ, obrazovka sa nenastavÃ­."
    WANT_KIOSK=no
  elif ! apt_install "$BROWSER" xserver-xorg xserver-xorg-legacy xserver-xorg-video-fbdev xinit x11-xserver-utils fonts-dejavu; then
    warn "Obrazovku sa nepodarilo nainÅ¡talovaÅ¥."
    WANT_KIOSK=no
  fi
fi

if [ "$WANT_KIOSK" = yes ]; then
  for group in video input render tty audio; do
    getent group "$group" >/dev/null && usermod -aG "$group" "$APP_USER"
  done

  mkdir -p /etc/X11
  printf 'allowed_users=anybody\nneeds_root_rights=yes\n' >/etc/X11/Xwrapper.config

  cat >"$APP_DIR/kiosk.sh" <<EOF
#!/bin/bash
# Obrazovka na TV: bez Å¡etriÄa a uspÃ¡vania, po pÃ¡de ju systemd spustÃ­ znova
xset s off
xset s noblank
xset -dpms
until curl -fsS -o /dev/null --max-time 3 http://localhost:$APP_PORT/health; do sleep 2; done
URL='http://localhost:$APP_PORT/#display'
if [ "$BROWSER" = firefox-esr ]; then
  exec firefox-esr --kiosk "\$URL"
fi
exec $BROWSER --kiosk --incognito --no-first-run --noerrdialogs --disable-infobars \\
  --disable-session-crashed-bubble --disable-translate --disable-gpu --password-store=basic \\
  --check-for-update-interval=31536000 --renderer-process-limit=2 --disk-cache-size=33554432 \\
  --user-data-dir=$HOME_DIR/browser "\$URL"
EOF
  chmod 755 "$APP_DIR/kiosk.sh"
  chown "$APP_USER:$APP_USER" "$APP_DIR/kiosk.sh"

  cat >/etc/systemd/system/tvdisplay-kiosk.service <<EOF
[Unit]
Description=Laudate obrazovka na TV
After=tvdisplay.service systemd-user-sessions.service
Wants=tvdisplay.service
Conflicts=getty@tty7.service

[Service]
User=$APP_USER
Environment=HOME=$HOME_DIR
PAMName=login
TTYPath=/dev/tty7
StandardInput=tty
StandardOutput=journal
StandardError=journal
ExecStart=/usr/bin/xinit $APP_DIR/kiosk.sh -- :0 vt7 -nolisten tcp -nocursor -keeptty
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF
fi

# --- ReÅ¡tart aplikÃ¡cie a zariadenia (z ovlÃ¡dania aj tlaÄidlami) --------

step "Nastavujem reÅ¡tart z ovlÃ¡dania a tlaÄidlÃ¡"
# PomocnÃ½ skript patrÃ­ rootovi; aplikÃ¡cia ho smie spustiÅ¥ cez sudo a vie iba tieto dve akcie
cat >/usr/local/sbin/laudate-system <<'EOF'
#!/bin/bash
# Laudate: reÅ¡tart aplikÃ¡cie alebo celÃ©ho zariadenia. Akcia sa zaradÃ­ do systemd (--no-block),
# takÅ¾e sa dokonÄÃ­, aj keÄ sa pri nej ukonÄÃ­ server, ktorÃ½ ju spustil.
case "${1:-}" in
  restart-app)
    systemctl --no-block restart tvdisplay.service
    if systemctl -q is-enabled tvdisplay-kiosk.service 2>/dev/null; then
      systemctl --no-block restart tvdisplay-kiosk.service
    fi
    exit 0 ;;
  reboot)
    systemctl --no-block reboot
    exit 0 ;;
  *) echo "PouÅ¾itie: laudate-system restart-app|reboot" >&2; exit 2 ;;
esac
EOF
chmod 755 /usr/local/sbin/laudate-system
chown root:root /usr/local/sbin/laudate-system
SUDOERS_TMP=$(mktemp)
printf '%s ALL=(root) NOPASSWD: /usr/local/sbin/laudate-system\n' "$APP_USER" >"$SUDOERS_TMP"
if ! command -v visudo >/dev/null || visudo -cf "$SUDOERS_TMP" >/dev/null; then
  install -m 440 -o root -g root "$SUDOERS_TMP" /etc/sudoers.d/laudate
else
  warn "ReÅ¡tart z ovlÃ¡dania sa nepodarilo nastaviÅ¥."
fi
rm -f "$SUDOERS_TMP"

if [ "$WANT_BUTTONS" = yes ]; then
  apt_install gpiod || warn "BalÃ­k gpiod sa nepodarilo nainÅ¡talovaÅ¥, tlaÄidlÃ¡ nebudÃº fungovaÅ¥."
  # Zapojenie (Orange Pi PC, 40-pinovÃ½ konektor): tlaÄidlo medzi pin a GND (pin 9),
  # vnÃºtornÃ½ pull-up drÅ¾Ã­ pin v 1, stlaÄenie ho spojÃ­ so zemou (0).
  if [ ! -f /etc/default/laudate-buttons ]; then
    cat >/etc/default/laudate-buttons <<'EOF'
# FyzickÃ© tlaÄidlÃ¡ a LED Laudate. Na Raspberry Pi sÃº ÄÃ­sla liniek GPIO inÃ© (pozri niÅ¾Å¡ie),
# fyzickÃ© piny na konektore sÃº rovnakÃ©. Orange Pi PC â€“ ÄÃ­sla liniek na Äipe GPIO:
# PA0 = 0, PA1 = 1, PA3 = 3, PC4 = 2*32+4 = 68 ...
# Pin 11 (PA1): tlaÄidlo reÅ¡tart aplikÃ¡cie â€“ podrÅ¾aÅ¥ 1 s
# Pin 13 (PA0): tlaÄidlo reÅ¡tart Orange Pi â€“ podrÅ¾aÅ¥ 3 s
# DruhÃ½ kontakt oboch tlaÄidiel: GND (pin 9)
# Pin 15 (PA3): LED reÅ¡tartu aplikÃ¡cie, pin 16 (PC4): LED reÅ¡tartu Orange Pi
# LED cez rezistor 220â€“330 Î© na GND (pin 14)
# Po zmene: sudo systemctl restart tvdisplay-buttons
# Raspberry Pi: pin 11 = GPIO17, pin 13 = GPIO27, pin 15 = GPIO22, pin 16 = GPIO23
BUTTON_APP_LINE=1
BUTTON_REBOOT_LINE=0
BUTTON_APP_HOLD=1
BUTTON_REBOOT_HOLD=3
# PrÃ¡zdne = nÃ¡jde sa automaticky (Orange Pi 1c20800.pinctrl, Raspberry Pi 5 pinctrl-rp1, Pi 4 pinctrl-bcm2711)
BUTTON_CHIP=
EOF
    if [ "$BOARD" = rpi ]; then
      sed -i 's/^BUTTON_APP_LINE=.*/BUTTON_APP_LINE=17/; s/^BUTTON_REBOOT_LINE=.*/BUTTON_REBOOT_LINE=27/' /etc/default/laudate-buttons
      printf 'LED_APP_LINE=22\nLED_REBOOT_LINE=23\n' >>/etc/default/laudate-buttons
    fi
  fi
  # NovÃ© nastavenia doplÅˆ aj do starÅ¡ieho sÃºboru (ostatnÃ© sa nemenia)
  add_default() { grep -q "^$1=" /etc/default/laudate-buttons || printf '%s=%s\n' "$1" "$2" >>/etc/default/laudate-buttons; }
  add_default LED_APP_LINE 3
  add_default LED_REBOOT_LINE 68
  add_default LAUDATE_PORT "$APP_PORT"
  cat >/usr/local/sbin/laudate-buttons <<'EOF'
#!/bin/bash
# Laudate: sleduje fyzickÃ© tlaÄidlÃ¡ a pri dostatoÄne dlhom stlaÄenÃ­ spustÃ­ reÅ¡tart.
# LED pri tlaÄidle svieti od stlaÄenia, kÃ½m sa akcia nevykonÃ¡: pri reÅ¡tarte aplikÃ¡cie
# zhasne, keÄ aplikÃ¡cia znova odpovedÃ¡; pri reÅ¡tarte zariadenia zhasne s jeho vypnutÃ­m.
. /etc/default/laudate-buttons
CHIP=${BUTTON_CHIP:-$(gpiodetect 2>/dev/null | awk '/1c20800|pinctrl-rp1|pinctrl-bcm2711|pinctrl-bcm2835/ {print $1; exit}')}
CHIP=${CHIP:-gpiochip0}
HEALTH="http://localhost:${LAUDATE_PORT:-5173}/health"
if gpioget --version 2>/dev/null | head -n1 | grep -q 'v2'; then
  read_lines() { gpioget -c "$CHIP" -b pull-up --numeric "$BUTTON_APP_LINE" "$BUTTON_REBOOT_LINE" 2>/dev/null; }
  hold_line() { gpioset -c "$CHIP" "$1=$2" 2>/dev/null & }
else
  read_lines() { gpioget -B pull-up "$CHIP" "$BUTTON_APP_LINE" "$BUTTON_REBOOT_LINE" 2>/dev/null; }
  hold_line() { gpioset --mode=signal "$CHIP" "$1=$2" 2>/dev/null & }
fi
if ! read_lines >/dev/null; then
  echo "Piny GPIO sa nedajÃº ÄÃ­taÅ¥ ($CHIP, linky $BUTTON_APP_LINE a $BUTTON_REBOOT_LINE)"
  exit 1
fi

# LED: hodnotu drÅ¾Ã­ proces gpioset; pri zmene sa starÃ½ ukonÄÃ­ a spustÃ­ novÃ½
declare -A LED_PID LED_STATE
led() { # led app|reboot 0|1
  local line
  if [ "$1" = app ]; then line=$LED_APP_LINE; else line=$LED_REBOOT_LINE; fi
  [ -n "$line" ] || return 0
  [ "${LED_STATE[$1]:-}" = "$2" ] && return 0
  if [ -n "${LED_PID[$1]:-}" ]; then
    kill "${LED_PID[$1]}" 2>/dev/null
    wait "${LED_PID[$1]}" 2>/dev/null
  fi
  hold_line "$line" "$2"
  LED_PID[$1]=$!
  LED_STATE[$1]=$2
}
cleanup() { for pid in "${LED_PID[@]}"; do kill "$pid" 2>/dev/null; done; }
trap cleanup EXIT
trap 'exit 0' TERM INT
led app 0
led reboot 0

# Po reÅ¡tarte aplikÃ¡cie poÄkaj, kÃ½m znova odpovedÃ¡ (najviac 2 minÃºty)
wait_for_app() {
  sleep 3
  for _ in $(seq 1 120); do
    curl -fsS -o /dev/null --max-time 2 "$HEALTH" && return 0
    sleep 1
  done
  echo "AplikÃ¡cia po reÅ¡tarte neodpovedÃ¡"
}

echo "TlaÄidlÃ¡: $CHIP, reÅ¡tart aplikÃ¡cie linka $BUTTON_APP_LINE (LED ${LED_APP_LINE:--}), reÅ¡tart zariadenia linka $BUTTON_REBOOT_LINE (LED ${LED_REBOOT_LINE:--})"
app=0
reboot=0
rebooting=0
while sleep 0.1; do
  read -r a r < <(read_lines) || continue
  if [ "$a" = 0 ]; then app=$((app + 1)); else app=0; fi
  if [ "$r" = 0 ]; then reboot=$((reboot + 1)); else reboot=0; fi
  [ "$rebooting" -eq 1 ] && continue
  # LED svieti, kÃ½m je tlaÄidlo stlaÄenÃ© (aj krÃ¡tko â€“ vidno, Å¾e stlaÄenie zariadenie zaznamenalo)
  if [ "$a" = 0 ] && [ "$app" -gt 0 ]; then led app 1; else led app 0; fi
  if [ "$r" = 0 ]; then led reboot 1; else led reboot 0; fi
  # Akcia sa spustÃ­ raz, keÄ tlaÄidlo drÅ¾Ã­ dosÅ¥ dlho (pri ÄalÅ¡om drÅ¾anÃ­ sa neopakuje)
  if [ "$reboot" -eq $((BUTTON_REBOOT_HOLD * 10)) ]; then
    echo "TlaÄidlo: reÅ¡tart zariadenia"
    rebooting=1 # LED ostane svietiÅ¥ aÅ¾ do vypnutia
    /usr/local/sbin/laudate-system reboot
  elif [ "$app" -eq $((BUTTON_APP_HOLD * 10)) ]; then
    echo "TlaÄidlo: reÅ¡tart aplikÃ¡cie"
    /usr/local/sbin/laudate-system restart-app
    wait_for_app
    echo "AplikÃ¡cia znova beÅ¾Ã­"
    led app 0
    app=-1000 # kÃ½m sa tlaÄidlo nepustÃ­, akcia sa nezopakuje
  fi
done
EOF
  chmod 755 /usr/local/sbin/laudate-buttons
  cat >/etc/systemd/system/tvdisplay-buttons.service <<'EOF'
[Unit]
Description=Laudate fyzickÃ© tlaÄidlÃ¡ (reÅ¡tart aplikÃ¡cie / zariadenia)
After=multi-user.target

[Service]
ExecStart=/usr/local/sbin/laudate-buttons
Restart=on-failure
RestartSec=30

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable tvdisplay-buttons.service >/dev/null 2>&1 || true
  systemctl restart tvdisplay-buttons.service 2>/dev/null || warn "SluÅ¾ba tlaÄidiel sa nespustila (journalctl -u tvdisplay-buttons)."
else
  systemctl disable --now tvdisplay-buttons.service 2>/dev/null || true
fi

# --- Spustenie -----------------------------------------------------------

step "SpÃºÅ¡Å¥am Laudate"
systemctl daemon-reload
systemctl enable tvdisplay.service >/dev/null
systemctl restart tvdisplay.service

if command -v ufw >/dev/null && ufw status 2>/dev/null | grep -q "Status: active"; then
  ufw allow "$APP_PORT/tcp" >/dev/null
fi

SERVER_OK=0
for _ in $(seq 1 30); do
  if curl -fsS -o /dev/null --max-time 3 "http://localhost:$APP_PORT/health"; then
    SERVER_OK=1
    break
  fi
  sleep 2
done
[ "$SERVER_OK" -eq 1 ] || die "Server sa nespustil. Pozri: journalctl -u tvdisplay -n 50"

REBOOT_NEEDED=0
if [ "$WANT_KIOSK" = yes ]; then
  systemctl enable tvdisplay-kiosk.service >/dev/null
  if [ "$DISPLAY_MANAGER_ACTIVE" -eq 1 ]; then
    # Vypne sa aÅ¾ po reÅ¡tarte, aby sa tento terminÃ¡l na pracovnej ploche nezavrel
    DM_UNIT=$(systemctl show -p Id --value display-manager 2>/dev/null || true)
    systemctl disable "${DM_UNIT:-display-manager}" 2>/dev/null || true
    REBOOT_NEEDED=1
  else
    systemctl restart tvdisplay-kiosk.service
  fi
else
  systemctl disable tvdisplay-kiosk.service 2>/dev/null || true
fi

IP_ADDRESS=$(hostname -I 2>/dev/null | awk '{print $1}')
IP_ADDRESS=${IP_ADDRESS:-<IP-adresa>}

echo
echo "Hotovo."
echo "  OvlÃ¡danie (mobil, PC): http://$IP_ADDRESS:$APP_PORT/#control"
echo "  Obrazovka:             http://$IP_ADDRESS:$APP_PORT/#display"
echo "  Stav a zÃ¡znamy:        systemctl status tvdisplay  /  journalctl -u tvdisplay -f"
echo "  Nastavenia:            $APP_DIR/.env (po zmene: sudo systemctl restart tvdisplay)"
if [ "$WANT_BUTTONS" = yes ]; then
  echo "  TlaÄidlÃ¡:              pin 11 = reÅ¡tart aplikÃ¡cie (1 s), pin 13 = reÅ¡tart $BOARD_NAME (3 s), druhÃ½ kontakt GND pin 9"
  echo "  LED:                   pin 15 = reÅ¡tart aplikÃ¡cie, pin 16 = reÅ¡tart $BOARD_NAME (cez rezistor 220â€“330 Î© na GND)"
fi
CURRENT_CHURCH_URL=$(sed -n 's/^CHURCH_DATA_URL=//p' "$APP_DIR/.env" | tail -n1)
CURRENT_NAS_URL=$(sed -n 's/^NAS_URL=//p' "$APP_DIR/.env" | tail -n1)
if [ -n "$CURRENT_CHURCH_URL" ]; then
  echo "  Piesne:                administrÃ¡cia $CURRENT_CHURCH_URL"
elif [ -n "$CURRENT_NAS_URL" ]; then
  echo "  Piesne:                NAS $CURRENT_NAS_URL"
  if tailscale_connected; then
    echo "  Tailscale:             pripojenÃ½ ($(tailscale ip -4 2>/dev/null | head -n1))"
  fi
else
  echo "  Piesne:                GitHub"
fi
if [ "$REBOOT_NEEDED" -eq 1 ]; then
  echo "  Obrazovka na TV sa zapne po reÅ¡tarte: sudo reboot"
fi
exit 0
